content:
深度优先搜索是一种用于遍历或搜索树或图的算法。所谓深度优先，就是说每次都尝试向更深的节点走。
要说个人理解的话，我的理解大概就是这样：
有一个人去某景区旅游，他现在在景区入口，景区里的一些路，有的能通到出口，有的不能。
这个人呢很倔强，他要一条一条去走，不走到路的尽头绝不回头。
他从第一条路走下去，走到头发现没路了，再回头到上一个分叉点，记下来这个分叉走过了；然后走另一个分叉，全部分叉走完了，再回到分叉点，再往回退一个分叉，记下来这个大分叉走过了没有路，然后走下一个分叉……


如果把这样一个景区抽象为一个图，那么也就是说，深度优先的搜索就是每次都尝试向更深的节点走。
DFS 搜索的实现方式一般是递归。也就是递归调用自身。在每次 DFS 遍历中都会对访问过的点打上标记，在遍历图的时候跳过已标记的点，以确保每个点只访问一次。
复杂度


时间复杂度
空间复杂度



O(n+m)O(n+m)O(n+m) | O(m)O(m)O(m)

实现寻找路线（走迷宫）bool DFS(int r,int c)&#123;    // 设定这个位置已经访问    visited[r][c]=true;     // 存储遍历时行走的参数，这样循环遍历的时候方便调用    // dr 为横着走, dc 为竖着走    // 顺序分别为：左 右 上 下    int dr[]=&#123;-1, 1, 0, 0&#125;;    int dc[]=&#123;0, 0, -1, 1&#125;;    if(/*当前位置为目标位置*/)return true;    // 遍历图，开始找路    for(int d=0;d&lt;4;++d)&#123;        int tr=r+dr[d]; // 横向        int tc=c+dc[d]; // 竖向        // 如果满足特定条件我就继续找，什么时候找到了 (DFS 返回 True) 就直接结束，这里不回溯        if(inMap(tr,tc)&amp;&amp;/*满足特定条件*/*&amp;&amp;!visited[tr][tc])            if(DFS(tr,tc))                return true;    &#125;    // 没找到    return false;&#125;bool inMap(int r,int c)&#123;    return r&gt;=0&amp;&amp;r&lt;n&amp;&amp;c&gt;=0&amp;&amp;c&lt;m;&#125;

上述代码调用 DFS 时，传入起点坐标，返回 true 则找到，false 则没找到。
例题深さ優先探索AC 代码：
#include&lt;iostream&gt;using namespace std;char map[505][505];bool visited[505][505];int n,m;bool DFS(int,int);bool inMap(int,int);int main()&#123;    cin &gt;&gt; n &gt;&gt; m;    for(int i=0;i&lt;n;++i)        for(int j=0;j&lt;m;++j)            cin &gt;&gt; map[i][j];        int startx,starty;    for(int i=0;i&lt;n;++i)        for(int j=0;j&lt;m;++j)        if(map[i][j]==&#x27;s&#x27;)&#123;            startx=i;            starty=j;        &#125;        bool res=DFS(startx,starty);    cout &lt;&lt; (res?&quot;Yes\n&quot;:&quot;No\n&quot;);    return 0;&#125;bool DFS(int r,int c)&#123;    visited[r][c]=true;    int dr[]=&#123;-1, 1, 0, 0&#125;;    int dc[]=&#123;0, 0, -1, 1&#125;;    if(map[r][c]==&#x27;g&#x27;)return true;    for(int d=0;d&lt;4;++d)&#123;        int tr=r+dr[d];        int tc=c+dc[d];        if(inMap(tr,tc)&amp;&amp;map[tr][tc]!=&#x27;#&#x27;&amp;&amp;!visited[tr][tc])            if(DFS(tr,tc))                return true;    &#125;    return false;&#125;bool inMap(int r,int c)&#123;    return r&gt;=0&amp;&amp;r&lt;n&amp;&amp;c&gt;=0&amp;&amp;c&lt;m;&#125;

灌水AC 代码 (已经过处理)：
#include &lt;iostream&gt;using namespace std;char matrix[30][40];int count = 0;void DFS(int, int);int main() &#123;    for (int i = 0; i &lt; 30; ++i)        for (int j = 0; j &lt; 40; ++j)            cin &gt;&gt; matrix[i][j]; // 调试用    DFS(0, 0);    cout &lt;&lt; count &lt;&lt; endl;    // cout &lt;&lt; 541 &lt;&lt; endl; 评测机要求必须直接输出结果    return 0;&#125;void DFS(int x, int y) &#123;    if (x &lt; 0 || x &gt;= 30 || y &lt; 0 || y &gt;= 40 || matrix[x][y] != &#x27;0&#x27;)        return;    count++;    matrix[x][y] = &#x27;2&#x27;;    DFS(x + 1, y);    DFS(x - 1, y);    DFS(x, y + 1);    DFS(x, y - 1);&#125;

在这里面没有单独存储已经遍历过的位置，是因为题目要求每走一步，就将这个地方标记为 222，也相当于已经标记过了。
最大连通AC 代码（已经过处理）：
#include &lt;iostream&gt;#include &lt;cmath&gt;using namespace std;char matrix[30][60];bool visited[30][60];int count=0,cntmax=0;void DFS(int,int);int main()&#123;  for(int i=0;i&lt;30;++i)    for(int j=0;j&lt;60;++j)      cin &gt;&gt; matrix[i][j];  for(int i=0;i&lt;30;++i)      for(int j=0;j&lt;60;++j)&#123;        count=0;        DFS(i,j);        cntmax=max(count,cntmax);      &#125;  cout &lt;&lt; cntmax &lt;&lt; endl;  // cout &lt;&lt; 148 &lt;&lt; endl; 评测机要求必须直接输出结果  return 0;&#125;void DFS(int x,int y)&#123;  if(x&lt;0||x&gt;=30||y&lt;0||y&gt;=60||matrix[x][y]==&#x27;0&#x27;||visited[x][y]==1)    return;  visited[x][y]=1;  count++;  int dx[4]=&#123;1,-1,0,0&#125;;  int dy[4]=&#123;0,0,-1,1&#125;;  for(int i=0;i&lt;4;++i)&#123;    int nextx=x+dx[i];    int nexty=y+dy[i];    if(nextx&gt;=0&amp;&amp;nextx&lt;30&amp;&amp;nexty&gt;=0&amp;&amp;nexty&lt;60&amp;&amp;matrix[nextx][nexty]==&#x27;1&#x27;&amp;&amp;visited[nextx][nexty]==0)&#123;      DFS(nextx,nexty);    &#125;  &#125;&#125;
